impl<T: gx::Real> Vector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[4];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t4);
        let t7 = (-t3).mul_add(T::from_i64(2), t5);
        t7
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (26 mul, 12 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Vector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[4];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t12 = t2 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t14);
        let t16 = t0.mul_add(t1, t6);
        let t17 = t1.mul_add(t2, t16);
        let t19 = (-t0).mul_add(t3, t13);
        let t20 = t1.mul_add(t3, t12);
        let t21 = t19 - t20;
        let t23 = t17.mul_add(T::from_i64(2), t15);
        let t24 = t21.mul_add(T::from_i64(4), t23);
        let t25 = t24.recip();
        let t27 = t1 * t25;
        let t29 = t3 * t25;
        let t30 = t0.mul_add(t25, t27);
        let t31 = t2.mul_add(t25, t30);
        let t33 = (-t29).mul_add(T::from_i64(2), t31);
        let t34 = x[0] * t33;
        let t35 = x[1] * t33;
        let t36 = x[2] * t33;
        let t37 = x[3] * t33;
        let t38 = x[4] * t33;
        Vector::from_coeffs([t34, t35, t36, t37, t38])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[3] * x[4];
        let p4 = x[0].mul_add(x[0], p1);
        let p5 = x[2].mul_add(x[2], p4);
        let p7 = (-p3).mul_add(T::from_i64(2), p5);
        let s0 = (p7).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1, t2, t3, t4]))
    }

}

impl<T: gx::Coef> gx::NewtonStep for Vector<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[4];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t4);
        let t7 = (-t3).mul_add(T::from_i64(2), t5);
        let t9 = (-t7).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t10 = x[0] * t9;
        let t11 = x[1] * t9;
        let t12 = x[2] * t9;
        let t13 = x[3] * t9;
        let t14 = x[4] * t9;
        let t15 = t10 * T::from_ratio(3, 2);
        let t16 = t11 * T::from_ratio(3, 2);
        let t17 = t12 * T::from_ratio(3, 2);
        let t18 = t13 * T::from_ratio(3, 2);
        let t19 = t14 * T::from_ratio(3, 2);
        Vector::from_coeffs([t15, t16, t17, t18, t19])
    }
}

#[doc = "The bivectors of rigid motions (the Lie algebra of motors): rotations `e23, e31, e12` and translations `e1i, e2i, e3i`."]
///
/// Blades, in coefficient order: `[e23, e31, e12, e1i, e2i, e3i]`.
///
/// `S` lists the open slots: `Twist` (that is, `Twist<()>`) is a value, `Twist<(A,)>` a
/// linear map from `A`, `Twist<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Twist<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 6],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Twist<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Twist<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Twist<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Twist<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Twist");
        for (b, c) in <Twist as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Twist {
    const N: usize = 6;
    const NAME: &'static str = "Twist";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e23", "e31", "e12", "e1i", "e2i", "e3i"];
    type Arr<X: gx::Elem> = [X; 6];
    type Mv<S: gx::Slots, T: gx::Coef> = Twist<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 6] {
        [f(0), f(1), f(2), f(3), f(4), f(5)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 6], mut f: impl FnMut(&X) -> Y) -> [Y; 6] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 6],
        b: &[Y; 6],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 6] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5])]
    }
}

