impl<T: gx::Real> Motor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (55 mul, 28 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Motor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t0.mul_add(t1, t6);
        let t18 = t0.mul_add(t3, t17);
        let t19 = t1.mul_add(t2, t10);
        let t20 = t2.mul_add(t3, t19);
        let t21 = t18 + t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 + t26;
        let t30 = t27 + t28;
        let t31 = t29 + t30;
        let t32 = t25 - t26;
        let t33 = x[0] * x[7];
        let t34 = t24 * t33;
        let t35 = x[1] * x[4];
        let t37 = (-t24).mul_add(t35, t34);
        let t38 = t27 - t28;
        let t39 = x[2] * x[5];
        let t41 = x[3] * x[6];
        let t42 = t24 * t41;
        let t43 = t24.mul_add(t39, t42);
        let t44 = x[0] * x[1];
        let t45 = x[2] * x[3];
        let t46 = t24 * t44;
        let t47 = t24 * t45;
        let t48 = x[0] * t31;
        let t49 = x[1] * t31;
        let t50 = x[2] * t31;
        let t51 = x[3] * t31;
        let t53 = x[1] * t43;
        let t55 = x[4] * t30;
        let t56 = x[6] * t47;
        let t59 = x[5] * t38;
        let t60 = x[5] * t47;
        let t63 = x[6] * t38;
        let t65 = x[0] * t43;
        let t67 = x[7] * t30;
        let t68 = -t49;
        let t69 = -t50;
        let t70 = -t51;
        let t71 = x[4].mul_add(t32, t55);
        let t72 = (-x[7]).mul_add(t46, t53);
        let t74 = t72.mul_add(T::from_i64(2), -t71);
        let t75 = (-x[5]).mul_add(t29, t59);
        let t76 = (-x[2]).mul_add(t37, t56);
        let t78 = t76.mul_add(T::from_i64(2), t75);
        let t79 = x[6].mul_add(t29, t63);
        let t80 = (-x[3]).mul_add(t37, t60);
        let t82 = t80.mul_add(T::from_i64(2), -t79);
        let t83 = (-x[7]).mul_add(t32, t67);
        let t84 = x[4].mul_add(t46, t65);
        let t86 = t84.mul_add(T::from_i64(2), t83);
        Motor::from_coeffs([t48, t68, t69, t70, t74, t78, t82, t86])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[3] * x[3];
        let p4 = x[0] * x[7];
        let p7 = x[3] * x[6];
        let p8 = x[0].mul_add(x[0], p1);
        let p9 = x[2].mul_add(x[2], p3);
        let p10 = p8 + p9;
        let p11 = (-x[1]).mul_add(x[4], p4);
        let p12 = x[2].mul_add(x[5], p7);
        let p13 = p11 - p12;
        let p14 = p13 * T::from_i64(2);
        let [s0, s1] = gx::study::rsqrt_nil(p10, p14);
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t5 = x[4] * s0;
        let t7 = x[5] * s0;
        let t9 = x[6] * s0;
        let t11 = x[7] * s0;
        let t12 = (-x[1]).mul_add(s1, t5);
        let t13 = (-x[2]).mul_add(s1, t7);
        let t14 = (-x[3]).mul_add(s1, t9);
        let t15 = x[0].mul_add(s1, t11);
        gx::Unit::new_unchecked(Motor::from_coeffs([t0, t1, t2, t3, t12, t13, t14, t15]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Motor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Motor<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 + t1;
        let t5 = t2 + t3;
        let t6 = t4 + t5;
        let t7 = t4 - T::from_i64(3);
        let t8 = t5 - T::from_i64(3);
        let t9 = x[0] * x[7];
        let t11 = (-x[1]).mul_add(x[4], t9);
        let t13 = x[3] * x[6];
        let t14 = x[2].mul_add(x[5], t13);
        let t16 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t17 = x[0] * x[1];
        let t18 = x[2] * x[3];
        let t19 = x[0] * t16;
        let t20 = x[1] * t16;
        let t21 = x[2] * t16;
        let t22 = x[3] * t16;
        let t24 = x[7] * t17;
        let t25 = x[4] * t1;
        let t27 = x[4] * t8;
        let t28 = x[5] * t2;
        let t30 = x[2] * t11;
        let t32 = x[5] * t7;
        let t35 = x[6] * t3;
        let t36 = x[3] * t11;
        let t37 = x[6] * t7;
        let t38 = x[7] * t0;
        let t40 = x[0] * t14;
        let t42 = x[7] * t8;
        let t43 = t19 * T::from_ratio(3, 2);
        let t44 = t20 * T::from_ratio(3, 2);
        let t45 = t21 * T::from_ratio(3, 2);
        let t46 = t22 * T::from_ratio(3, 2);
        let t47 = (-x[1]).mul_add(t14, t24);
        let t48 = x[4].mul_add(t0, t27);
        let t51 = (-t48).mul_add(T::from_ratio(1, 2), t47);
        let t52 = (-t25).mul_add(T::from_ratio(3, 2), t51);
        let t53 = (-x[6]).mul_add(t18, t30);
        let t54 = x[5].mul_add(t3, t32);
        let t57 = (-t54).mul_add(T::from_ratio(1, 2), t53);
        let t58 = (-t28).mul_add(T::from_ratio(3, 2), t57);
        let t59 = (-x[5]).mul_add(t18, t36);
        let t60 = x[6].mul_add(t2, t37);
        let t63 = (-t60).mul_add(T::from_ratio(1, 2), t59);
        let t64 = (-t35).mul_add(T::from_ratio(3, 2), t63);
        let t65 = x[4].mul_add(t17, t40);
        let t66 = x[7].mul_add(t1, t42);
        let t69 = (-t66).mul_add(T::from_ratio(1, 2), t65);
        let t70 = (-t38).mul_add(T::from_ratio(3, 2), t69);
        Motor::from_coeffs([t43, t44, t45, t46, t52, t58, t64, t70])
    }
}

impl<T: gx::Real> gx::Log<Twist<(), T>> for gx::Unit<Motor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Twist<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p1 = x[2] * x[2];
        let p4 = x[2] * x[5];
        let p6 = x[1].mul_add(x[1], p1);
        let p7 = x[3].mul_add(x[3], p6);
        let p8 = -p7;
        let p9 = x[1].mul_add(x[4], p4);
        let p10 = x[3].mul_add(x[6], p9);
        let p11 = p10 * T::from_i64(2);
        let [h0, h1] = gx::study::log_coeffs_rotation((x[0], x[7]), (p8, p11));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        let t4 = x[4] * h0;
        let t6 = x[5] * h0;
        let t8 = x[6] * h0;
        let t9 = (-x[1]).mul_add(h1, t4);
        let t10 = (-x[2]).mul_add(h1, t6);
        let t11 = (-x[3]).mul_add(h1, t8);
        Twist::from_coeffs([t0, t1, t2, t9, t10, t11])
        })
    }
}

#[doc = "The even subalgebra: all conformal versors of even grade (rotors, translators, dilators, transversions)."]
///
/// Blades, in coefficient order: `[1, e23, e31, e12, e1o, e2o, e3o, e1i, e2i, e3i, eoi, e23oi, e31oi, e12oi, e123o, e123i]`.
///
/// `S` lists the open slots: `Even` (that is, `Even<()>`) is a value, `Even<(A,)>` a
/// linear map from `A`, `Even<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Even<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 16],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Even<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Even<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Even<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Even<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Even");
        for (b, c) in <Even as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Even {
    const N: usize = 16;
    const NAME: &'static str = "Even";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["1", "e23", "e31", "e12", "e1o", "e2o", "e3o", "e1i", "e2i", "e3i", "eoi", "e23oi", "e31oi", "e12oi", "e123o", "e123i"];
    type Arr<X: gx::Elem> = [X; 16];
    type Mv<S: gx::Slots, T: gx::Coef> = Even<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 16] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14), f(15)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 16], mut f: impl FnMut(&X) -> Y) -> [Y; 16] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14]), f(&a[15])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 16],
        b: &[Y; 16],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 16] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14]), f(&a[15], &b[15])]
    }
}

