impl<T: gx::Real> Even<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t5 = x[5] * x[8];
        let t8 = x[11] * x[11];
        let t10 = x[13] * x[13];
        let t11 = x[14] * x[15];
        let t12 = x[0].mul_add(x[0], t1);
        let t13 = x[2].mul_add(x[2], t3);
        let t14 = t12 + t13;
        let t15 = x[10].mul_add(x[10], t8);
        let t16 = x[12].mul_add(x[12], t10);
        let t17 = t15 + t16;
        let t18 = t14 - t17;
        let t19 = x[4].mul_add(x[7], t5);
        let t20 = x[6].mul_add(x[9], t11);
        let t21 = t19 + t20;
        let t23 = (-t21).mul_add(T::from_i64(2), t18);
        t23
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Even<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p1 = x[12] * x[12];
        let p3 = x[14] * x[15];
        let p4 = x[11].mul_add(x[11], p1);
        let p5 = x[13].mul_add(x[13], p4);
        let p7 = p3.mul_add(T::from_i64(2), p5);
        let p8 = -p7;
        let [h0, h1] = gx::study::log_coeffs_q(x[0], p8);
        let t0 = x[11] * h1;
        let t1 = x[12] * h1;
        let t2 = x[13] * h1;
        let t3 = x[14] * h1;
        let t4 = x[15] * h1;
        let t6 = x[4] * t4;
        let t8 = x[10] * t0;
        let t10 = x[5] * t4;
        let t12 = x[10] * t1;
        let t14 = x[6] * t4;
        let t16 = x[10] * t2;
        let t19 = x[5] * t2;
        let t20 = x[6] * t1;
        let t23 = x[5] * h0;
        let t24 = x[6] * t0;
        let t26 = x[4] * t1;
        let t28 = x[6] * h0;
        let t31 = x[8] * t2;
        let t32 = x[9] * t1;
        let t34 = x[7] * t2;
        let t36 = x[9] * t0;
        let t39 = x[8] * t0;
        let t40 = x[9] * h0;
        let t43 = x[3] * t2;
        let t44 = x[10] * h0;
        let t45 = x[1].mul_add(h0, t6);
        let t46 = x[7].mul_add(t3, t8);
        let t47 = t45 + t46;
        let t48 = x[2].mul_add(h0, t10);
        let t49 = x[8].mul_add(t3, t12);
        let t50 = t48 + t49;
        let t51 = x[3].mul_add(h0, t14);
        let t52 = x[9].mul_add(t3, t16);
        let t53 = t51 + t52;
        let t54 = x[4].mul_add(h0, t20);
        let t55 = x[1].mul_add(t3, t19);
        let t56 = t54 - t55;
        let t57 = x[4].mul_add(t2, t23);
        let t58 = x[2].mul_add(t3, t24);
        let t59 = t57 - t58;
        let t60 = x[5].mul_add(t0, t28);
        let t61 = x[3].mul_add(t3, t26);
        let t62 = t60 - t61;
        let t63 = x[7].mul_add(h0, t31);
        let t64 = x[1].mul_add(t4, t32);
        let t65 = t63 - t64;
        let t66 = x[8].mul_add(h0, t36);
        let t67 = x[2].mul_add(t4, t34);
        let t68 = t66 - t67;
        let t69 = x[7].mul_add(t1, t40);
        let t70 = x[3].mul_add(t4, t39);
        let t71 = t69 - t70;
        let t72 = (-x[1]).mul_add(t0, t44);
        let t73 = x[2].mul_add(t1, t43);
        let t74 = t72 - t73;
        Bivector::from_coeffs([t47, t50, t53, t56, t59, t62, t65, t68, t71, t74])
        })
    }
}

#[doc = "The odd subalgebra."]
///
/// Blades, in coefficient order: `[e1, e2, e3, eo, ei, e23o, e31o, e12o, e23i, e31i, e12i, e1oi, e2oi, e3oi, e123, e123oi]`.
///
/// `S` lists the open slots: `Odd` (that is, `Odd<()>`) is a value, `Odd<(A,)>` a
/// linear map from `A`, `Odd<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Odd<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 16],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Odd<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Odd<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Odd<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Odd<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Odd");
        for (b, c) in <Odd as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Odd {
    const N: usize = 16;
    const NAME: &'static str = "Odd";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "e3", "eo", "ei", "e23o", "e31o", "e12o", "e23i", "e31i", "e12i", "e1oi", "e2oi", "e3oi", "e123", "e123oi"];
    type Arr<X: gx::Elem> = [X; 16];
    type Mv<S: gx::Slots, T: gx::Coef> = Odd<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 16] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14), f(15)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 16], mut f: impl FnMut(&X) -> Y) -> [Y; 16] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14]), f(&a[15])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 16],
        b: &[Y; 16],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 16] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14]), f(&a[15], &b[15])]
    }
}

