        let v = self.c;
        let m1 = v[1] * v[1];
        let m3 = v[3] * v[3];
        let m4 = v[0] * v[7];
        let m7 = v[3] * v[6];
        let m8 = v[0].mul_add(v[0], m1);
        let m9 = v[2].mul_add(v[2], m3);
        let m10 = m8 + m9;
        let m11 = (-v[1]).mul_add(v[4], m4);
        let m12 = v[2].mul_add(v[5], m7);
        let m13 = m11 - m12;
