impl<S: gx::Slots, T: gx::Coef> gx::TransformInv<Even<S, T>> for gx::Unit<Odd<(), T>> {
    type Output = Even<S, T>;
    #[inline(always)]
    fn transform_inv(self, x: Even<S, T>) -> Even<S, T> {
        gx::Transform::transform(gx::Unit::new_unchecked(self.into_inner().reverse()), x)
    }
}

